import React, { useState, useMemo } from 'react';
import { User, Listing, Post, Review } from '../types';
import { X, CheckCircle2, MapPin, Star, Store, MessageSquare, ExternalLink, Grid, Layers, Folder, Tag, Sparkles } from 'lucide-react';

interface SellerProfileModalProps {
  seller?: User;
  sellerId?: string;
  users?: User[];
  listings: Listing[];
  posts: Post[];
  reviews: Review[];
  onClose: () => void;
  onOpenChat: (sellerId: string) => void;
  onSelectListing: (listing: Listing) => void;
}

export const SellerProfileModal: React.FC<SellerProfileModalProps> = ({
  seller: initialSeller,
  sellerId,
  users,
  listings,
  posts,
  reviews,
  onClose,
  onOpenChat,
  onSelectListing
}) => {
  const seller = initialSeller || users?.find(u => u.id === sellerId) || {
    id: sellerId || 'unknown',
    name: 'Business Vendor',
    username: '@vendor',
    email: 'vendor@bizsocial.com',
    avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=400',
    role: 'seller_premium',
    bio: 'Verified business seller on BizSocial.',
    isVerified: true,
    subscriptionStatus: 'premium',
    location: 'Global Hub',
    followersCount: 150,
    followingCount: 30,
    rating: 5.0,
    reviewsCount: 12,
    totalSales: 45,
    createdAt: 'Joined 2024'
  } as User;

  const [isFollowing, setIsFollowing] = useState(false);
  const [activeTab, setActiveTab] = useState<'listings' | 'posts' | 'reviews'>('listings');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewGrouping, setViewGrouping] = useState<'all' | 'grouped'>('grouped');

  const sellerListings = useMemo(() => listings.filter(l => l.sellerId === seller.id), [listings, seller.id]);
  const sellerPosts = useMemo(() => posts.filter(p => p.sellerId === seller.id), [posts, seller.id]);
  const sellerReviews = useMemo(() => reviews.filter(r => r.sellerId === seller.id), [reviews, seller.id]);

  // Extract all distinct categories used by this seller (from listings + customCategories)
  const availableCategories = useMemo(() => {
    const set = new Set<string>();
    if (seller.customCategories) {
      seller.customCategories.forEach(c => set.add(c));
    }
    sellerListings.forEach(l => {
      if (l.storeCategory) set.add(l.storeCategory);
    });
    return Array.from(set);
  }, [seller.customCategories, sellerListings]);

  // Filtered listings based on selectedCategory
  const filteredListings = useMemo(() => {
    if (selectedCategory === 'all') return sellerListings;
    return sellerListings.filter(l => (l.storeCategory || 'General') === selectedCategory);
  }, [sellerListings, selectedCategory]);

  // Group listings by store category
  const groupedListings = useMemo(() => {
    const map: Record<string, Listing[]> = {};
    sellerListings.forEach(l => {
      const cat = l.storeCategory || 'General Collection';
      if (!map[cat]) map[cat] = [];
      map[cat].push(l);
    });
    return map;
  }, [sellerListings]);

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/70 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto animate-in fade-in">
      <div className="bg-white rounded-3xl max-w-2xl w-full border border-slate-200 shadow-2xl overflow-hidden relative my-8">
        
        {/* Cover Image */}
        <div className="h-36 bg-gradient-to-r from-slate-900 via-indigo-950 to-purple-950 relative">
          {seller.coverImage && (
            <img src={seller.coverImage} alt="" className="w-full h-full object-cover opacity-80" />
          )}
          <button
            onClick={onClose}
            className="absolute top-3 right-3 bg-slate-950/60 hover:bg-slate-950 text-white p-2 rounded-full transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Profile Info */}
        <div className="px-6 pb-6 relative pt-0">
          
          <div className="flex justify-between items-end -mt-10 mb-4">
            <img
              src={seller.avatar}
              alt={seller.name}
              className="w-20 h-20 rounded-full object-cover border-4 border-white shadow-md bg-white"
            />

            <div className="flex items-center gap-2">
              <button
                onClick={() => setIsFollowing(!isFollowing)}
                className={`px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                  isFollowing
                    ? 'bg-slate-100 text-slate-700 border border-slate-300'
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-xs'
                }`}
              >
                {isFollowing ? '✓ Following' : '+ Follow Shop'}
              </button>

              <button
                onClick={() => {
                  onClose();
                  onOpenChat(seller.id);
                }}
                className="p-2 border border-slate-200 hover:bg-slate-50 text-slate-700 rounded-xl transition-colors cursor-pointer"
                title="Direct Chat with Seller"
              >
                <MessageSquare className="w-4 h-4" />
              </button>
            </div>
          </div>

          <div className="space-y-2">
            <div>
              <div className="flex items-center gap-1.5">
                <h2 className="text-lg font-black text-slate-900">{seller.name}</h2>
                {seller.isVerified && <CheckCircle2 className="w-4 h-4 text-sky-500 fill-sky-50" />}
              </div>
              <span className="text-xs text-slate-400">@{seller.username}</span>
            </div>

            <p className="text-xs text-slate-700 leading-relaxed">{seller.bio}</p>

            <div className="flex flex-wrap items-center gap-4 text-xs text-slate-500 pt-1 font-medium">
              <span className="flex items-center gap-1"><MapPin className="w-3.5 h-3.5" /> {seller.location}</span>
              <span><strong>{seller.followersCount + (isFollowing ? 1 : 0)}</strong> Followers</span>
              <span><strong>{seller.followingCount}</strong> Following</span>
              <span className="flex items-center gap-1 text-amber-600 font-bold">
                <Star className="w-3.5 h-3.5 fill-current" /> {seller.rating} ({seller.reviewsCount} reviews)
              </span>
            </div>

            {seller.customStorefrontUrl && (
              <div className="pt-1">
                <a
                  href={`https://${seller.customStorefrontUrl}`}
                  target="_blank"
                  rel="noreferrer"
                  className="text-xs text-indigo-600 font-bold hover:underline inline-flex items-center gap-1"
                >
                  <ExternalLink className="w-3.5 h-3.5" /> {seller.customStorefrontUrl}
                </a>
              </div>
            )}
          </div>

          {/* Storefront Navigation Tabs */}
          <div className="flex items-center justify-between border-b border-slate-200 mt-6 pb-0">
            <div className="flex items-center gap-4 text-xs font-bold text-slate-600">
              <button
                onClick={() => setActiveTab('listings')}
                className={`pb-2.5 px-1 border-b-2 transition-colors cursor-pointer flex items-center gap-1.5 ${
                  activeTab === 'listings' ? 'border-indigo-600 text-indigo-600' : 'border-transparent hover:text-slate-900'
                }`}
              >
                <Store className="w-4 h-4" />
                <span>Store Collections ({sellerListings.length})</span>
              </button>
              <button
                onClick={() => setActiveTab('posts')}
                className={`pb-2.5 px-1 border-b-2 transition-colors cursor-pointer ${
                  activeTab === 'posts' ? 'border-indigo-600 text-indigo-600' : 'border-transparent hover:text-slate-900'
                }`}
              >
                Feed Posts ({sellerPosts.length})
              </button>
              <button
                onClick={() => setActiveTab('reviews')}
                className={`pb-2.5 px-1 border-b-2 transition-colors cursor-pointer ${
                  activeTab === 'reviews' ? 'border-indigo-600 text-indigo-600' : 'border-transparent hover:text-slate-900'
                }`}
              >
                Reviews ({sellerReviews.length})
              </button>
            </div>

            {/* View Mode Switcher for Storefront */}
            {activeTab === 'listings' && availableCategories.length > 0 && (
              <div className="hidden sm:flex items-center gap-1 mb-2 bg-slate-100 p-0.5 rounded-lg text-[11px] font-bold">
                <button
                  onClick={() => setViewGrouping('grouped')}
                  className={`px-2 py-0.5 rounded-md transition-all cursor-pointer ${
                    viewGrouping === 'grouped' ? 'bg-white text-slate-900 shadow-2xs' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  By Category
                </button>
                <button
                  onClick={() => setViewGrouping('all')}
                  className={`px-2 py-0.5 rounded-md transition-all cursor-pointer ${
                    viewGrouping === 'all' ? 'bg-white text-slate-900 shadow-2xs' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  All Items
                </button>
              </div>
            )}
          </div>

          {/* Tab Content */}
          <div className="pt-4 max-h-80 overflow-y-auto pr-1">
            {activeTab === 'listings' && (
              <div className="space-y-4">
                
                {/* SELLER CATEGORY PILLS BAR (when buyer wants to filter or click specific categories) */}
                {availableCategories.length > 0 && (
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-[11px] font-extrabold uppercase tracking-wider text-slate-400 flex items-center gap-1">
                        <Folder className="w-3 h-3 text-indigo-500" /> Filter by Category
                      </span>
                      <span className="text-[10px] text-slate-400 font-semibold">
                        {availableCategories.length} Categories Created
                      </span>
                    </div>

                    <div className="flex flex-wrap gap-1.5">
                      <button
                        onClick={() => {
                          setSelectedCategory('all');
                          setViewGrouping('grouped');
                        }}
                        className={`px-2.5 py-1 rounded-xl text-xs font-bold transition-all cursor-pointer border ${
                          selectedCategory === 'all'
                            ? 'bg-slate-900 text-white border-slate-900 shadow-xs'
                            : 'bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100'
                        }`}
                      >
                        All Categories ({sellerListings.length})
                      </button>

                      {availableCategories.map((cat) => {
                        const count = sellerListings.filter(l => (l.storeCategory || 'General') === cat).length;
                        return (
                          <button
                            key={cat}
                            onClick={() => {
                              setSelectedCategory(cat);
                              setViewGrouping('all');
                            }}
                            className={`px-2.5 py-1 rounded-xl text-xs font-bold transition-all cursor-pointer border flex items-center gap-1.5 ${
                              selectedCategory === cat
                                ? 'bg-indigo-600 text-white border-indigo-600 shadow-xs'
                                : 'bg-slate-50 text-slate-700 border-slate-200 hover:border-indigo-300 hover:bg-indigo-50/50'
                            }`}
                          >
                            <span>{cat}</span>
                            <span className={`text-[10px] px-1.5 py-0.2 rounded-full font-black ${
                              selectedCategory === cat ? 'bg-indigo-700 text-white' : 'bg-slate-200 text-slate-700'
                            }`}>
                              {count}
                            </span>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* GROUPED VIEW: Displays separate header for each category */}
                {viewGrouping === 'grouped' && selectedCategory === 'all' ? (
                  <div className="space-y-5">
                    {Object.entries(groupedListings).map(([catName, items]) => (
                      <div key={catName} className="space-y-2.5 p-3.5 bg-slate-50/70 rounded-2xl border border-slate-200/70">
                        <div className="flex items-center justify-between border-b border-slate-200/60 pb-1.5">
                          <h4 className="font-extrabold text-xs text-indigo-950 flex items-center gap-1.5">
                            <Tag className="w-3.5 h-3.5 text-indigo-600" />
                            <span>{catName}</span>
                            <span className="text-[10px] bg-indigo-100 text-indigo-800 px-1.5 py-0.2 rounded-md font-bold">
                              {items.length} {items.length === 1 ? 'item' : 'items'}
                            </span>
                          </h4>
                          <button
                            onClick={() => {
                              setSelectedCategory(catName);
                              setViewGrouping('all');
                            }}
                            className="text-[10px] font-bold text-indigo-600 hover:underline cursor-pointer"
                          >
                            View only this →
                          </button>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                          {items.map((l) => (
                            <div
                              key={l.id}
                              onClick={() => {
                                onSelectListing(l);
                                onClose();
                              }}
                              className="p-2.5 bg-white rounded-xl border border-slate-200 cursor-pointer hover:border-indigo-400 hover:shadow-xs transition-all flex items-center gap-2.5 group"
                            >
                              <img src={l.images[0]} alt="" className="w-13 h-13 rounded-lg object-cover group-hover:scale-105 transition-transform" />
                              <div className="min-w-0 flex-1">
                                <h5 className="font-bold text-xs text-slate-900 group-hover:text-indigo-600 transition-colors line-clamp-1">
                                  {l.title}
                                </h5>
                                <div className="flex items-center justify-between mt-1">
                                  <span className="text-xs font-black text-slate-900">${l.price.toFixed(2)}</span>
                                  <span className="text-[9px] font-extrabold text-emerald-600 bg-emerald-50 px-1.5 py-0.2 rounded">
                                    In Stock
                                  </span>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}

                    {sellerListings.length === 0 && (
                      <div className="text-center py-8 text-slate-400 text-xs font-medium">
                        No products posted by this seller yet.
                      </div>
                    )}
                  </div>
                ) : (
                  /* FLAT / FILTERED LIST VIEW */
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {filteredListings.map((l) => (
                      <div
                        key={l.id}
                        onClick={() => {
                          onSelectListing(l);
                          onClose();
                        }}
                        className="p-2.5 bg-slate-50 hover:bg-white rounded-xl border border-slate-200 cursor-pointer hover:border-indigo-400 hover:shadow-xs transition-all flex items-center gap-2.5 group"
                      >
                        <img src={l.images[0]} alt="" className="w-13 h-13 rounded-lg object-cover group-hover:scale-105 transition-transform" />
                        <div className="min-w-0 flex-1">
                          <span className="text-[9px] font-bold text-indigo-600 uppercase tracking-wider block truncate">
                            {l.storeCategory || 'General Collection'}
                          </span>
                          <h4 className="font-bold text-xs text-slate-900 group-hover:text-indigo-600 transition-colors line-clamp-1">
                            {l.title}
                          </h4>
                          <div className="flex items-center justify-between mt-1">
                            <span className="text-xs font-black text-slate-900">${l.price.toFixed(2)}</span>
                            <span className="text-[9px] text-slate-400 font-semibold">{l.condition}</span>
                          </div>
                        </div>
                      </div>
                    ))}

                    {filteredListings.length === 0 && (
                      <div className="col-span-2 text-center py-8 text-slate-400 text-xs font-medium">
                        No products found in category "{selectedCategory}".
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'posts' && (
              <div className="space-y-3">
                {sellerPosts.map((p) => (
                  <div key={p.id} className="p-3 bg-slate-50 rounded-xl border border-slate-200 text-xs">
                    <p className="text-slate-800 leading-relaxed mb-1">{p.content}</p>
                    <span className="text-[10px] text-slate-400">{p.createdAt} • ❤️ {p.likesCount}</span>
                  </div>
                ))}
                {sellerPosts.length === 0 && (
                  <div className="text-center py-8 text-slate-400 text-xs font-medium">
                    No feed updates posted yet.
                  </div>
                )}
              </div>
            )}

            {activeTab === 'reviews' && (
              <div className="space-y-2">
                {sellerReviews.map((r) => (
                  <div key={r.id} className="p-3 bg-slate-50 rounded-xl text-xs space-y-1">
                    <div className="flex justify-between items-center font-bold text-slate-900">
                      <span>{r.buyerName}</span>
                      <span className="text-amber-500">{"★".repeat(r.rating)}</span>
                    </div>
                    <p className="text-slate-600">{r.comment}</p>
                  </div>
                ))}
                {sellerReviews.length === 0 && (
                  <div className="text-center py-8 text-slate-400 text-xs font-medium">
                    No buyer reviews yet.
                  </div>
                )}
              </div>
            )}
          </div>

        </div>

      </div>
    </div>
  );
};
